CREATE TABLE IF NOT EXISTS sovereign_conductor_batches_v1 (batch_id TEXT PRIMARY KEY,source TEXT NOT NULL,scope TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','cancelled')),cursor TEXT,processed INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,max_items_per_cycle INTEGER NOT NULL DEFAULT 100 CHECK(max_items_per_cycle BETWEEN 1 AND 500),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sovereign_batches_status ON sovereign_conductor_batches_v1(status,created_at);
CREATE TABLE IF NOT EXISTS sovereign_conductor_batch_items_v1 (batch_id TEXT NOT NULL,item_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','claimed','completed','failed')),receipt_json TEXT,PRIMARY KEY(batch_id,item_id));
CREATE INDEX IF NOT EXISTS idx_sovereign_batch_items_state ON sovereign_conductor_batch_items_v1(batch_id,state);
